import{_ as a,o as n,c as t,au as l}from"./chunks/framework.CKsBWDFD.js";import"./chunks/theme.Buk3xez4.js";const _=JSON.parse('{"title":"The Seven Elements","description":"","frontmatter":{"next":{"text":"Elemental Combat","link":"/guide/elements/elemental_combat"}},"headers":[],"relativePath":"guide/elements/The_Seven_Elements.md","filePath":"guide/elements/The Seven Elements.md","lastUpdated":1783267680000}'),s={name:"guide/elements/The_Seven_Elements.md"};function o(m,e,r,i,p,c){return n(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="The_Seven_Elements" tabindex="-1">The Seven Elements <a class="header-anchor" href="#The_Seven_Elements" aria-label="Permalink to “The Seven Elements”">​</a></h1><p>In Genshin Impact <em>and</em> <strong>Seven Elements</strong>, there exists the seven Elements: <span class="pyro"><strong>Pyro</strong></span>, <span class="hydro"><strong>Hydro</strong></span>, <span class="anemo"><strong>Anemo</strong></span>, <span class="electro"><strong>Electro</strong></span>, <span class="dendro"><strong>Dendro</strong></span>, <span class="cryo"><strong>Cryo</strong></span>, and <span class="geo"><strong>Geo</strong></span>.</p><p>By combining specific elements together, you&#39;re able to trigger <a href="./Elemental_Reactions">Elemental Reactions</a>! Each element is its own damage type, and non-elemental damage is considered <strong>Physical</strong>, which isn&#39;t an element.</p><p>When applying an element to an entity, it will decay over time, so there isn&#39;t any concept of &quot;infinite elemental application&quot;!</p><h2 id="Elemental_Combat" tabindex="-1">Elemental Combat <a class="header-anchor" href="#Elemental_Combat" aria-label="Permalink to “Elemental Combat”">​</a></h2><p>    <em>Main page: <a href="./Elemental_Combat">Elemental Combat</a></em></p><p>In Seven Elements, you may infuse your attacks with one of the seven Elements and deal Elemental Damage of that element.</p><h2 id="Elemental_Reactions" tabindex="-1">Elemental Reactions <a class="header-anchor" href="#Elemental_Reactions" aria-label="Permalink to “Elemental Reactions”">​</a></h2><p>    <em>Main page: <a href="./Elemental_Reactions">Elemental Reactions</a></em></p><p>When applying an element on a target already afflicted with an element, various Elemental Reactions may be triggered.</p><h2 id="Elemental_Application_Systems" tabindex="-1">Elemental Application Systems <a class="header-anchor" href="#Elemental_Application_Systems" aria-label="Permalink to “Elemental Application Systems”">​</a></h2><p>    <em>See also: <a href="./Elemental_Gauge_Theory">Elemental Gauge Theory</a> and <a href="./Internal_Cooldown">Internal Cooldown</a></em></p><p>Elements aren&#39;t just a state of <em>applied</em> or <em>removed</em>, they are rather represented as a certain amount of <em><a href="./Elemental_Gauge_Theory#Elemental_Auras_and_the_Aura_Tax">gauge units</a></em>. Elements can also only be applied in certain intervals, where elemental damage dealt within the interval <em>only</em> deals elemental damage but does not apply an Element.</p>',13)])])}const g=a(s,[["render",o]]);export{_ as __pageData,g as default};
